for _k, _v in MORE3.items(): MORE2.setdefault(_k, []).extend(_v)
import re as _re
for c in DATA["cities"]:
    pre = c["items"][0]["id"].split("-")[0]
    used = {i["id"] for i in c["items"]}
    for (typ, tier, name, desc, addr, url) in MORE2.get(c["id"], []):
        slug = _re.sub(r"[^a-z0-9]+", "", name.lower().encode("ascii", "ignore").decode())[:14]
        iid = f"{pre}-{slug}"
        n = 2
        while iid in used: iid = f"{pre}-{slug}{n}"; n += 1
        used.add(iid)
        c["items"].append({"id": iid, "type": typ, "tier": tier, "name": name, "desc": desc, "address": addr, "url": url,
                           "photo": c["photo"], "credit": c["credit"]})

# --- 4 catégories par ville (demande de Marie, 27/11/2026) : spas et dégustations -> Activités
DATA["types"] = {
    "logement": {"label": "Logement", "emoji": "🏡"},
    "activite": {"label": "Activités", "emoji": "🎉"},
    "restauration": {"label": "Restauration", "emoji": "🍽️"},
    "soiree": {"label": "Bars et boîtes", "emoji": "🪩"},
}
RESTO = {"ldn-sketch", "ldn-bus", "bud-dinner", "lille-tablestoques", "lyon-halles"}
for c in DATA["cities"]:
    for it in c["items"]:
        n = it["name"].lower()
        if it["type"] == "chef" or it["id"] in RESTO or "afternoon tea" in n or "croisière-dîner" in n \
           or "gastronomique" in n or "halles paul bocuse" in n:
            it["type"] = "restauration"
        elif "taproom" in n:
            it["type"] = "soiree"
        elif it["type"] in ("spa", "fun", "activite"):
            it["type"] = "activite"

root = pathlib.Path(__file__).resolve().parent.parent
(root / "data").mkdir(exist_ok=True)
# Photos de Louise : toutes les images déposées dans assets/louise/
POS = {"01-metro-selfie": "66% 40%", "02-parc-trio": "47% 32%", "03-dos-a-dos": "72% 28%", "04-cuisine": "38% 36%",
       "05-frange": "55% 32%", "06-profil": "36% 36%", "07-bac": "48% 28%", "08-metro": "76% 38%",
       "09-photomaton": "50% 12%", "10-floue": "62% 45%"}
DATA["louise"] = [{"src": "assets/louise/" + f.name, "pos": POS.get(f.stem, "50% 35%")}
                  for f in sorted((root / "assets" / "louise").glob("*"))
                  if f.suffix.lower() in (".jpg", ".jpeg", ".png", ".webp")]
txt = json.dumps(DATA, ensure_ascii=False, indent=1)
(root / "data" / "evjf.json").write_text(txt, encoding="utf-8")
(root / "data" / "embedded_data.js").write_text("window.EVJF_DATA = " + txt + ";\n", encoding="utf-8")
n = sum(len(c["items"]) for c in DATA["cities"])
print(f"OK : {len(DATA['cities'])} villes, {n} propositions, {len(DATA['louise'])} photos de Louise")
